  hi_heap HI (PQM.aown (PQM.AST lvX bX kX kx kgx kbx gx) ++ LBX) cr1 M1 (m_vmmaps model1) ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (kx' : PM.vstr) (kgx' : Z) (cr' : credit),
      regs_preserved R0 R' -> cm M' -> world M' ->
      (forall a m, sp1 <= a -> a + m <= 2 ^ 64 -> (a + m <= oa + 24 \/ oa + 48 <= a) -> L5C.agree_on M1 M' a m) ->
      adaptor_at M' oa ov (PQM.AST lvX bX kX kx' kgx' kbx gx) -> PQM.ks_ok PQM.SMK kx' kgx' -> PM.vs_size kx' = PM.vs_size kx + nchars v ->
      PMSP.credit_keep cr1 cr' (PQM.pot_adaptor L (PQM.AST lvX bX kX kx kgx kbx gx)) (PQM.pot_adaptor L (PQM.AST lvX bX kX kx' kgx' kbx gx)) ->
      model_but_vm model1 model' -> hi_heap HI (PQM.aown (PQM.AST lvX bX kX kx' kgx' kbx gx) ++ LBX) cr' M' (m_vmmaps model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' ra M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx0 R0 0x3d128 M1 model1) K.
